/**
 * 크라스 그레이딩 테마 데이터.
 *
 * 크라스는 **위가 광원이고 아래가 잔불이다.** 카르곤과 정확히 뒤집힌 배치이고, 아래 값 전부가
 * 그 한 문장의 결과다:
 *
 * - 비네트 코어를 **위로** 올렸다(`centerY` −0.08). 카르곤은 발밑 용암을 보여 주려고 코어를
 *   내렸지만, 크라스에서 정보가 있는 곳은 무너진 천장 사이로 빛이 들어오는 위쪽이다.
 * - **스플릿 톤이 반대 방향이다**(`warmthDirection` −1). 하이라이트는 흐린 하늘 확산광이라
 *   차갑고(`gain` 0xd8e6ff), 암부는 바닥 잔불의 바운스라 따뜻하다(`shadow` 0xff1400).
 *   부호를 코드에 박았다면 이 행성에서 단조성 검사가 통째로 뒤집혀 "스플릿이 없다"로
 *   오판됐을 것이다.
 * - 따뜻한 가산은 여전히 하단에만 둔다(`warm.startY` 0.5). 잔불은 바닥에 있다.
 *
 * ## 예산이 어떻게 배분됐는가
 * 감쇠 항 셋(비네트·cool·gain)은 같은 예산에서 먹는다. gain 틴트가 카르곤(황백, 휘도 0.879)
 * 보다 밝은 청백(휘도 0.897)이라 gain 이 먹는 감쇠가 조금 줄었고, 그만큼을 비네트가 아니라
 * **cool 형상**에 남겨 뒀다 — 크라스에서 위쪽을 눌러야 할 이유(잿빛 하늘)가 카르곤보다 크다.
 *
 * 여기 남길 주석은 **크라스 근거**뿐이다. 메커니즘 근거는 계약·레이어에 남긴다.
 */

import type { GradeTheme } from '../../contracts/grade.js';

export const KRAS_GRADE: GradeTheme = {
  themeId: 'kras',
  alpha: {
    // 현대 AAA 비네트의 통상 대역(20~40%) 안쪽.
    vignette: 0.28,
    /*
     * 하단 잔불 반사광. 시차의 `far-smoulder`·`near-ember` 도 같은 방향으로 밝히므로 여기는
     * "바닥에 불이 남아 있다"는 국소 근거가 있는 최소량만 남긴다.
     */
    warm: 0.04,
    /*
     * 가장자리 **형상** 담당. 전역 색온도 분리는 gain 이 맡는다. 카르곤(0.06)과 같은 값이지만
     * 틴트가 더 어두워(휘도 0.414 vs 0.443) 실제로 먹는 감쇠는 조금 크다.
     */
    cool: 0.06,
    /*
     * 상한에 붙어 있다. 틴트가 순한(휘도 0.897) 청백이라 알파를 키워도 총 감쇠가 10.3% 의
     * 0.3 배, 즉 3.1% 에 그치기 때문이다.
     */
    gain: 0.3,
    /*
     * 0.04. 카르곤(0.055)보다 낮은 이유는 산술이다 — warmth 교차점이 [0,1] 안에 있어야
     * "스플릿"이고, 이 방향(암부가 따뜻함)에서는 lift 의 R−B 가 1.0 으로 최대라 0.055 를
     * 쓰면 교차점이 1.31 로 밀려 화면이 전역 웜 캐스트가 된다. 0.04 에서 교차점 0.87.
     */
    shadow: 0.04,
    // 밴딩을 깨는 최소량. 이 이상은 화면이 지저분해진다.
    grain: 0.035,
  },
  /** 코어를 살짝 **위로** 올려 아래쪽 잔해를 더 누른다. `outer` 는 최원거리 모서리(약 1.49)가 거의 최대에 닿는 값. */
  vignette: { centerY: -0.08, inner: 0.62, outer: 1.55 },
  /** 화면 **하단 1/4** 밖으로는 한 픽셀도 밝히지 않는다(시차 레인과의 중복 해소). */
  warm: { startY: 0.5, sideFalloff: 0.42 },
  /** 상단(잿빛 하늘)과 좌우를 함께 누른다. */
  cool: { topStart: -0.2, topEnd: -1, sideStart: 0.6, sideEnd: 1.05 },
  tint: {
    /** 바닥 잔불의 반사광. 색상각 341.8° 로 크라스 안전 골짜기 안이다. */
    warm: 0xff5a8c,
    /** 잿빛 하늘의 차가운 슬레이트. 하이라이트와 색온도를 가른다. */
    cool: 0x5a6a92,
    /** 무채에 가깝게 두어 색을 밀지 않는다. */
    grain: 0xb0b0b8,
    /**
     * 하이라이트 청백 = 흐린 하늘 확산광. B=255 라 흰 화소의 B 손실이 0 이고, 그래서 g=1 에서
     * B 채널 오버플로 여유가 정확히 0 인 채로 등호에 붙는다 — **`shadow` 틴트의 B 가 0 이어야
     * 하는 이유가 이것이다.** 카르곤의 R/B 관계를 그대로 거울에 비춘 구조다.
     */
    gain: 0xd8e6ff,
    /**
     * 암부 적색 = 바닥 잔불 바운스. R=255·G=20·B=0 을 고른 이유는 **채도 대비 휘도가 싸기**
     * 때문이다(상대휘도 0.269). 암부 R−B 를 최대로 벌리면서 절대 휘도 상승은 0.011 에 그친다.
     */
    shadow: 0xff1400,
  },
  /** 하늘이 광원이므로 하이라이트가 차갑고 암부가 따뜻하다 — 카르곤과 반대. */
  warmthDirection: -1,
};
